import RNA
import random
import os
from multiprocessing import Pool

TARGET = open('/tmp/target396.txt').read().strip()
N = len(TARGET)

MD = RNA.md(); MD.dangles=2; MD.temperature=310.15

# parse target pairs
st=[]; TP={}
for i,c in enumerate(TARGET):
    if c=='(': st.append(i)
    elif c==')':
        j=st.pop(); TP[(j,i)]=True

def fold(seq):
    fc = RNA.fold_compound(seq, MD, RNA.OPTION_DEFAULT)
    ss, mfe = fc.mfe()
    return ss

def score(seq):
    ss = fold(seq)
    return RNA.bp_distance(ss, TARGET)

def init_seq():
    # GC pairs, A unpaired, but alternate GC/AU to reduce over-stacking
    seq=['A']*N
    pairs_list=[]
    st=[]
    for i,c in enumerate(TARGET):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); pairs_list.append((j,i))
    for k,(i,j) in enumerate(pairs_list):
        if k%2==0:
            seq[i]='G'; seq[j]='C'
        else:
            seq[i]='A'; seq[j]='U'
    return ''.join(seq)

def anneal(seed):
    r = random.Random(seed)
    seq = init_seq()
    # perturb start
    seq=list(seq)
    for i in range(N):
        if r.random()<0.3:
            seq[i]=r.choice('ACGU')
    seq=''.join(seq)
    cur = score(seq)
    best = cur
    best_seq = seq
    T = 3.0
    for it in range(3000):
        T = 3.0 * (1 - it/3000.0) + 0.05
        # mutate 1-2 positions
        seql=list(seq)
        k=r.randint(1,2)
        for _ in range(k):
            i=r.randint(0,N-1)
            seql[i]=r.choice('ACGU')
        nseq=''.join(seql)
        ns=score(nseq)
        d = ns-cur
        if d<=0 or r.random()<pow(2.71828, -d/T):
            seq=nseq; cur=ns
            if cur<best:
                best=cur; best_seq=seq
                if best==0:
                    return (0, seq)
    return (best, best_seq)

if __name__=='__main__':
    nproc=min(128, os.cpu_count())
    print('procs',nproc,flush=True)
    best_d=N; best_seq=None
    with Pool(nproc) as p:
        for d,seq in p.imap_unordered(anneal, range(256)):
            if d<best_d:
                best_d=d; best_seq=seq
                print('best',d,flush=True)
                if d==0:
                    p.terminate(); break
    print('FINAL',best_d,flush=True)
    if best_seq:
        open('/tmp/cand.txt','w').write(best_seq)
        print('LEN',len(best_seq),flush=True)
        print('SEQ '+best_seq,flush=True)
