PAIRSET=set(PAIRS)

def fold(seq):
    fc=RNA.fold_compound(seq, MD, RNA.OPTION_DEFAULT)
    ss,mfe=fc.mme() if hasattr(fc,'mme') else fc.mfe()
    return ss

def foldm(seq):
    fc=RNA.fold_compound(seq, MD, RNA.OPTION_DEFAULT)
    ss,mfe=fc.mfe()
    return ss

def pairs_of(ss):
    s=[]; ps=set()
    for i,c in enumerate(ss):
        if c=='(': s.append(i)
        elif c==')':
            j=s.pop(); ps.add((j,i))
    return ps

def score(seq):
    ss=foldm(seq)
    ps=pairs_of(ss)
    # wrong = missing + spurious
    miss=len(PAIRSET-ps); spur=len(ps-PAIRSET)
    return miss+spur, miss, spur

def init(seed):
    r=random.Random(seed)
    seq=['A']*N
    for k,(i,j) in enumerate(PAIRS):
        # mostly AU/GU weak pairs, some GC
        choice=r.choice([('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')])
        seq[i]=choice[0]; seq[j]=choice[1]
    return ''.join(seq)

def hill(seed):
    r=random.Random(seed)
    seq=list(init(seed))
    cur,_,_=score(''.join(seq))
    best=cur; bestseq=''.join(seq)
